head.b:skin:
:root { --bg-main: #141414; --net-red: #e50914; --text: #fff; }
body { background-color: var(--bg-main); color: var(--text); font-family: 'Roboto', sans-serif; margin: 0; padding: 0; overflow-x: hidden; -webkit-user-select: none; user-select: none; }
#navbar-iframe { display: none !important; }
::-webkit-scrollbar { width: 8px; background: #141414; }
::-webkit-scrollbar-thumb { background: #333; border-radius: 4px; }

/* === PROFILE GATE === */
.profile-gate { position: fixed; inset: 0; background: #141414; z-index: 9999; display: flex; flex-direction: column; align-items: center; justify-content: center; transition: 0.4s ease-out; }
.profile-gate.hidden { opacity: 0; pointer-events: none; transform: scale(1.1); }
.profile-grid { display: flex; gap: 2vw; flex-wrap: wrap; justify-content: center; }
.profile-item { display: flex; flex-direction: column; align-items: center; cursor: pointer; transition: 0.2s; }
.profile-item:hover { transform: scale(1.05); }
.profile-avatar { width: 10vw; height: 10vw; min-width: 100px; min-height: 100px; max-width: 150px; max-height: 150px; border-radius: 4px; background-size: cover; border: 3px solid transparent; transition: 0.2s; background-image: url('https://upload.wikimedia.org/wikipedia/commons/0/0b/Netflix-avatar.png'); }
.profile-item:hover .profile-avatar { border-color: white; }
.profile-name { margin-top: 15px; color: grey; font-size: 1.2vw; transition: 0.2s; font-weight: 500; }
.profile-item:hover .profile-name { color: white; }

/* === NAVBAR === */
.nav { position: fixed; top: 0; width: 100%; height: 68px; padding: 0 4%; display: flex; align-items: center; justify-content: space-between; z-index: 100; transition: 0.4s; background: linear-gradient(to bottom, rgba(0,0,0,0.7) 10%, transparent); }
.nav.black { background-color: #141414; }

/* WIDGET STYLES */
.header-section { display: flex; align-items: center; }
.header-widget h1 { color: var(--net-red); font-size: 25px; font-weight: 900; text-transform: uppercase; margin: 0; cursor: pointer; }
.header-widget img { max-height: 40px; }
.header-widget p { display: none; }

.menu-section { margin-left: 20px; }
.menu-widget ul { display: flex; list-style: none; gap: 20px; padding: 0; margin: 0; }
.menu-widget a { color: #e5e5e5; text-decoration: none; font-size: 14px; font-weight: 500; transition: 0.2s; }
.menu-widget a:hover { color: #b3b3b3; }
@media(max-width: 768px) { .menu-section { display: none; } }

/* MOBILE MENU */
.mobile-menu { position: fixed; top: 68px; left: 0; width: 100%; background: #141414; border-top: 1px solid #333; display: flex; flex-direction: column; padding: 20px; gap: 20px; z-index: 90; transform: translateY(-150%); transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.mobile-menu.open { transform: translateY(0); }
.mobile-link { font-size: 16px; font-weight: 700; color: #e5e5e5; text-decoration: none; }
.mobile-link:hover { color: white; }

/* === HERO BANNER === */
.banner { width: 100%; background-size: cover; background-position: center top; position: relative; color: white; }
@media(max-width: 767px) { .banner { height: 65vh; min-height: 400px; background-position: center center; } .banner-title { font-size: 2.5rem !important; max-width: 100% !important; } .banner-desc { display: none !important; } }
@media(min-width: 768px) { .banner { height: 90vh; max-height: 850px; } .banner-title { font-size: 5rem; max-width: 50%; } .banner-desc { display: -webkit-box; } }
.banner-contents { margin-left: 4%; height: 100%; display: flex; flex-direction: column; justify-content: center; padding-top: 60px; position: relative; z-index: 10; }
.banner-title { font-weight: 800; padding-bottom: 0.3rem; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); line-height: 1.1; }
.banner-desc { width: 100%; max-width: 600px; line-height: 1.3; padding-top: 1rem; font-size: 1.2rem; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); font-weight: 500; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.banner-btns { margin-top: 1.5rem; display: flex; gap: 1rem; }
.btn { cursor: pointer; outline: none; border: none; font-weight: 700; border-radius: 4px; padding: 0.8rem 2.4rem; display: flex; align-items: center; gap: 10px; transition: 0.2s; font-size: 1.2rem; }
.btn-play { background-color: white; color: black; }
.btn-more { background-color: rgba(109, 109, 110, 0.7); color: white; }
.banner-fade { height: 10rem; background-image: linear-gradient(180deg, transparent, rgba(20,20,20,0.61), #141414); position: absolute; bottom: 0; width: 100%; z-index: 1; }

/* === ROWS & GRIDS === */
.row { margin: 20px 0; padding-left: 4%; position: relative; }
.row-title { font-size: 1.4vw; font-weight: 600; margin-bottom: 10px; color: #e5e5e5; display: inline-block; cursor: pointer; }
@media(max-width: 768px) { .row-title { font-size: 18px; } }
.row-posters { display: flex; overflow-y: hidden; overflow-x: scroll; padding: 10px 0 20px 0; gap: 10px; scrollbar-width: none; align-items: center; }
.row-posters::-webkit-scrollbar { display: none; }
.row-poster { flex: 0 0 auto; width: 160px; aspect-ratio: 2/3; object-fit: cover; border-radius: 4px; transition: transform 450ms; cursor: pointer; }
@media(max-width: 768px) { .row-poster { width: 120px; } }
.row-poster:hover { transform: scale(1.08); opacity: 1; z-index: 10; }

/* TOP 10 */
.rank-container { position: relative; flex: 0 0 auto; width: 160px; height: 180px; display: flex; align-items: center; cursor: pointer; transition: transform 450ms; margin-right: 10px; }
@media(min-width: 768px) { .rank-container { width: 240px; height: 200px; margin-right: 20px; } }
.rank-num { font-size: 120px; font-weight: 900; color: #000; -webkit-text-stroke: 4px #595959; position: absolute; left: -15px; bottom: 0; line-height: 0.9; z-index: 1; letter-spacing: -10px; }
.rank-img { height: 100%; width: 65%; object-fit: cover; border-radius: 4px; position: absolute; right: 0; z-index: 2; }
.rank-container:hover { transform: scale(1.05); z-index: 10; }

/* SEARCH GRID */
.search-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 20px; }
@media(min-width: 768px) { .search-grid { grid-template-columns: repeat(6, 1fr); gap: 15px; padding: 40px; } }

/* === PLAYER UI === */
.modal-overlay { position: fixed; inset: 0; background: #141414; z-index: 200; overflow-y: auto; transform: translateY(100%); transition: 0.3s; }
.modal-overlay.active { transform: translateY(0); }
.player-responsive { width: 100%; position: relative; padding-top: 56.25%; background: black; overflow: hidden; }
@media(min-width: 1400px) { .player-responsive { padding-top: 0; height: 80vh; max-width: 1600px; margin: 0 auto; } }
.player-responsive iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0; }
.back-btn { position: absolute; top: 20px; left: 20px; z-index: 20; color: white; font-size: 40px; cursor: pointer; filter: drop-shadow(0 0 5px black); }
.modal-info { padding: 30px 4%; max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: 1fr 380px; gap: 40px; }
@media(max-width: 1024px) { .modal-info { grid-template-columns: 1fr; } }

/* EPISODES & DOWNLOADS */
.season-tabs { display: flex; gap: 15px; overflow-x: auto; padding-bottom: 10px; border-bottom: 1px solid #333; margin-bottom: 15px; }
.tab-btn { background: transparent; color: #999; padding: 8px 0; font-weight: 700; cursor: pointer; border-radius: 0; white-space: nowrap; font-size: 16px; border-bottom: 3px solid transparent; }
.tab-btn.active { color: white; border-bottom-color: var(--net-red); }
.ep-row { display: flex; align-items: center; padding: 10px; border-bottom: 1px solid #2a2a2a; transition: 0.2s; gap: 15px; border-radius: 4px; }
.ep-row:hover { background: #222; }
.ep-idx { color: #d2d2d2; font-size: 1.5em; font-weight: bold; width: 20px; flex-shrink: 0; text-align: center; }
.ep-thumb-wrap { width: 120px; aspect-ratio: 16/9; position: relative; flex-shrink: 0; border-radius: 4px; overflow: hidden; }
.ep-thumb { width: 100%; height: 100%; object-fit: cover; }
.ep-meta { flex: 1; min-width: 0; }
.ep-title { font-weight: 700; font-size: 0.95em; color: white; margin-bottom: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dl-icon-btn { color: #e5e5e5; font-size: 24px; padding: 10px; border-radius: 50%; transition: 0.2s; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.dl-icon-btn:hover { background: rgba(255,255,255,0.1); color: white; }
.dl-movie-row { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 25px; border-top: 1px solid #333; padding-top: 20px; }
.dl-btn { border: 1px solid #4ade80; color: #4ade80; padding: 10px 24px; border-radius: 4px; font-weight: 700; font-size: 14px; text-transform: uppercase; transition: 0.2s; text-decoration: none; display: inline-flex; align-items: center; gap: 8px; }
.dl-btn:hover { background: #4ade80; color: black; }

/* FOOTER */
.site-footer { padding: 50px 10%; color: #808080; font-size: 13px; margin-top: 50px; max-width: 1000px; margin-left: auto; margin-right: auto; }
.footer-links { display: grid; grid-template-columns: repeat(4, 1fr); gap: 15px; margin-bottom: 20px; }
.footer-links a { color: #808080; text-decoration: none; }
.footer-links a:hover { text-decoration: underline; }

/* UTILS */
#post-body-raw { display: none; }
.search-box { position: fixed; top: 0; left: 0; width: 100%; height: 70px; background: #141414; z-index: 110; display: flex; align-items: center; padding: 0 4%; transform: translateY(-100%); transition: 0.3s; }
.search-box.open { transform: translateY(0); }
.search-close { font-size: 30px; cursor: pointer; color: white; margin-left: 20px; }

body.script:
//

// PROTECTION
document.addEventListener("keydown", function(e) {
    if (e.ctrlKey && (e.key === "u" || e.key === "U" || e.key === "s" || e.key === "S")) e.preventDefault();
    if (e.key === "F12" || (e.ctrlKey && e.shiftKey && e.key === "I")) e.preventDefault();
});
(function(){})();

const API_KEY = '3b522d97585d4de7c6c1d0f346940389';
const IMG_BASE = 'https://image.tmdb.org/t/p/original';
const IMG_W500 = 'https://image.tmdb.org/t/p/w500';
const TMDB_BASE = 'https://api.themoviedb.org/3';

// CREDIT
const fc = "JmNvcHk7IDIwMjYgQWxsIFJpZ2h0cyBSZXNlcnZlZCA8YSBocmVmPSJodHRwczovL3Byb3RlbXBsYXRlcy5pbi8iIHN0eWxlPSJvcGFjaXR5OjAiIHRhcmdldD0iX2JsYW5rIiA+UHJvVGVtcGxhdGVzPC9hPg==";
document.getElementById('f-credit').innerHTML = atob(fc);

// PROFILE
function checkProfile() { if(localStorage.getItem('conflix_user')) { document.getElementById('profile-gate').classList.add('hidden'); document.getElementById('app-root').classList.add('visible'); } }
function selectProfile(name) { localStorage.setItem('conflix_user', name); checkProfile(); }
function switchProfile() { localStorage.removeItem('conflix_user'); window.location.reload(); }
checkProfile();

// UI
window.addEventListener('scroll', () => {
    const nav = document.getElementById('nav');
    if(window.scrollY > 50) nav.classList.add('black'); else nav.classList.remove('black');
});

// Auto Menu
const pcMenu = document.querySelector('.menu-widget ul');
if(pcMenu) {
    const mobileMenu = document.getElementById('mobile-menu');
    const links = pcMenu.querySelectorAll('a');
    links.forEach(l => {
        const a = document.createElement('a');
        a.href = l.href; a.innerText = l.innerText; a.className = 'mobile-link';
        mobileMenu.appendChild(a);
    });
}

function toggleMobileMenu() { document.getElementById('mobile-menu').classList.toggle('open'); }
function toggleSearch() {
    const box = document.getElementById('search-box');
    const main = document.getElementById('main-view');
    const results = document.getElementById('search-results-container');
    box.classList.toggle('open');
    if(box.classList.contains('open')) {
        document.getElementById('search-input').focus();
    } else {
        results.classList.add('hidden');
        main.classList.remove('hidden');
    }
}
document.getElementById('search-input').addEventListener('keyup', async (e) => {
    if(e.key === 'Enter') {
        const query = e.target.value;
        const main = document.getElementById('main-view');
        const resultsBox = document.getElementById('search-results-container');
        const grid = document.getElementById('search-grid');
        main.classList.add('hidden');
        resultsBox.classList.remove('hidden');
        grid.innerHTML = '<div class="text-gray-500">Loading...</div>';

        const res = await fetch(`/feeds/posts/default?alt=json&q=${encodeURIComponent(query)}`);
        const data = await res.json();
        const posts = data.feed.entry;

        if(!posts) { grid.innerHTML = 'No results found.'; return; }
        grid.innerHTML = '';
        posts.forEach(post => {
            const link = post.link.find(l=>l.rel==='alternate').href;
            let img = getMatch(post.content.$t, 'poster-url');
            if(!img && post.media$thumbnail) img = post.media$thumbnail.url.replace('/s72-c/', '/w342/'); 
            grid.innerHTML += `<div class="row-poster" onclick="window.location.href='${link}'"><img src="${img}" class="w-full h-full object-cover rounded"/></div>`;
        });
    }
});

// APP LOGIC
const isHome = window.location.pathname === '/' || window.location.pathname === '/index.html';
const isSingle = document.getElementById('app-player') !== null;
const isLabel = document.getElementById('label-loader') !== null;

if (isHome) {
    initHome();
} else if (isSingle) {
    initPlayer();
} else if (isLabel) {
    const path = window.location.pathname;
    const label = path.split('/').pop();
    loadRow(`/feeds/posts/default/-/${label}?alt=json&max-results=20`, 'search-grid', 'Results', false, true);
    document.getElementById('main-view').classList.add('hidden');
    document.getElementById('search-results-container').classList.remove('hidden');
}

async function initHome() {
    try {
        const res = await fetch('/feeds/posts/default?alt=json&max-results=5');
        const data = await res.json();
        const randomPost = data.feed.entry[Math.floor(Math.random() * data.feed.entry.length)];
        const title = randomPost.title.$t;
        const content = randomPost.content.$t;
        const link = randomPost.link.find(l=>l.rel==='alternate').href;
        const tmdb = await fetchTMDB(title);
        const backdrop = tmdb ? IMG_BASE + tmdb.backdrop_path : (getMatch(content, 'backdrop-url') || '');
        const desc = tmdb ? tmdb.overview : getMatch(content, 'data-desc');
        document.getElementById('banner').style.backgroundImage = `url('${backdrop}')`;
        document.getElementById('banner-title').innerText = title;
        document.getElementById('banner-desc').innerText = desc;
        const openLink = () => window.location.href = link;
        document.getElementById('btn-play').onclick = openLink;
        document.getElementById('btn-more').onclick = openLink;
    } catch(e) {}

    loadRow('/feeds/posts/default?alt=json&max-results=10', 'row-trending', '');
    loadTop10('/feeds/posts/default/-/Original?alt=json&max-results=10', 'row-top-movies', 'Em alta agora');
    loadTop10('/feeds/posts/default/-/Cidade Ocidental?alt=json&max-results=10', 'row-top-tv', 'Top 10 semanal');
    loadRow('/feeds/posts/default/-/Curiosidades?alt=json&max-results=10', 'row-anime', 'Séries');
    loadRow('/feeds/posts/default/-/Lendas?alt=json&max-results=10', 'row-action', 'Filmes');
    loadRow('/feeds/posts/default/-/Brasília?alt=json&max-results=10', 'row-comedy', 'Comedy Movies');
}

async function loadRow(url, containerId, title, isRank=false, isGrid=false) {
    const container = document.getElementById(containerId);
    try {
        const res = await fetch(url);
        const data = await res.json();
        const posts = data.feed.entry;
        if(!posts) return;
        let html = isGrid ? '' : `<h2 class="row-title">${title}</h2><div class="row-posters">`;
        posts.forEach((post, idx) => {
            const link = post.link.find(l=>l.rel==='alternate').href;
            let img = getMatch(post.content.$t, 'poster-url');
            if(!img && post.media$thumbnail) img = post.media$thumbnail.url.replace('/s72-c/', '/w342/');
            if(isGrid) {
                html += `<div class="row-poster" onclick="window.location.href='${link}'"><img src="${img}" class="w-full h-full object-cover rounded"/></div>`;
            } else {
                html += `<img src="${img}" class="row-poster" onclick="window.location.href='${link}'" />`;
            }
        });
        if(!isGrid) html += `</div>`;
        container.innerHTML = html;
    } catch(e) {}
}

async function loadTop10(url, containerId, title) {
    const container = document.getElementById(containerId);
    try {
        const res = await fetch(url);
        const data = await res.json();
        const posts = data.feed.entry;
        if(!posts) return;
        let html = `<h2 class="row-title">${title}</h2><div class="row-posters">`;
        posts.forEach((post, idx) => {
            const link = post.link.find(l=>l.rel==='alternate').href;
            let img = getMatch(post.content.$t, 'poster-url');
            if(!img && post.media$thumbnail) img = post.media$thumbnail.url.replace('/s72-c/', '/w342/');
            html += `<div class="rank-container" onclick="window.location.href='${link}'"><span class="rank-num">${idx + 1}</span><img src="${img}" class="rank-img"/></div>`;
        });
        html += `</div>`;
        container.innerHTML = html;
    } catch(e) {}
}

async function initPlayer() {
    const raw = document.getElementById('post-body-raw');
    const app = document.getElementById('app-player');
    const getData = (cls) => raw.querySelector('.' + cls)?.innerText || '';
    const basicData = {
        title: getData('data-title'), desc: getData('data-desc'), meta: getData('data-meta'),
        seasons: Array.from(raw.querySelectorAll('.data-season')),
        servers: Array.from(raw.querySelectorAll('.data-stream')),
        downloads: Array.from(raw.querySelectorAll('.data-dl'))
    };
    let tmdb = await fetchTMDB(basicData.title);
    let meta = { ...basicData };
    if(tmdb) { meta.desc = tmdb.overview; meta.id = tmdb.id; }

    app.innerHTML = `
        <div class="modal-overlay active">
            <i class='bx bx-left-arrow-alt back-btn' onclick="window.history.back()"></i>
            <div class="player-responsive"><iframe id="main-player" src="" frameborder="0" allowfullscreen></iframe></div>
            <div class="modal-info">
                <div class="flex-1">
                    <h1 class="text-4xl font-bold mb-3 text-white">${meta.title}</h1>
                    <div class="flex gap-4 text-gray-400 font-bold mb-6 text-sm">
                        <span class="text-green-500">98% Match</span><span>${meta.meta}</span><span class="border border-gray-500 px-1 text-xs rounded text-white">HD</span>
                    </div>
                    <p class="text-white leading-relaxed text-lg">${meta.desc}</p>
                    ${meta.downloads.length > 0 ? `<div class="dl-movie-row">${meta.downloads.map(l => `<a href="${l.href}" target="_blank" class="dl-btn"><i class='bx bxs-download'></i> ${l.innerText}</a>`).join('')}</div>` : ''}
                </div>
                <div class="md:w-[400px]">
                    ${meta.seasons.length > 0 ? `<div id="season-tabs" class="season-tabs"></div><div id="ep-list" class="ep-container">Loading Episodes...</div>` : `<h3 class="text-xl font-bold mb-4 text-white">Servers</h3><div class="flex flex-wrap gap-3">${meta.servers.map(l => `<button onclick="playUrl('${l.href}')" class="bg-white text-black px-6 py-2 rounded font-bold hover:bg-gray-300">${l.innerText}</button>`).join('')}</div>`}
                </div>
            </div>
        </div>`;

    if(meta.seasons.length > 0 && meta.id) { loadSeasons(meta.id, meta.seasons); } else if(meta.servers.length > 0) { playUrl(meta.servers[0].href); }
}

async function loadSeasons(tmdbId, seasonNodes) {
    const tabs = document.getElementById('season-tabs');
    seasonNodes.forEach((node, i) => {
        const sNum = i+1;
        const btn = document.createElement('div');
        btn.className = `tab-btn ${i===0 ? 'active' : ''}`;
        btn.innerText = `Season ${sNum}`;
        btn.onclick = () => loadSeasonData(tmdbId, sNum, node, btn);
        tabs.appendChild(btn);
    });
    loadSeasonData(tmdbId, 1, seasonNodes[0], tabs.children[0]);
}

async function loadSeasonData(tmdbId, sNum, node, btn) {
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const list = document.getElementById('ep-list');
    list.innerHTML = 'Loading...';

    const seasonData = await fetch(`${TMDB_BASE}/tv/${tmdbId}/season/${sNum}?api_key=${API_KEY}`).then(r=>r.json());
    const temp = document.createElement('div');
    temp.innerHTML = node.innerHTML;
    const streams = Array.from(temp.querySelectorAll('button'));
    const downloads = Array.from(temp.querySelectorAll('a'));

    let html = '';
    streams.forEach((el, idx) => {
        const url = el.getAttribute('onclick')?.match(/'(.*?)'/)?.[1];
        if(!url) return;
        const ep = seasonData.episodes ? seasonData.episodes[idx] : null;
        const title = ep ? ep.name : el.innerText;
        const desc = ep ? ep.overview : '';
        const img = ep && ep.still_path ? IMG_W500 + ep.still_path : 'https://via.placeholder.com/160x90?text=No+Img';
        const num = idx+1;
        const dlLink = downloads[idx] ? downloads[idx].href : null;

        html += `<div class="ep-row"><div class="flex items-center gap-3 flex-1 cursor-pointer" onclick="playUrl('${url}')"><span class="ep-idx">${num}</span><div class="ep-thumb-wrap"><img src="${img}" class="ep-thumb" loading="lazy"/><div class="ep-play-icon"><i class='bx bx-play text-3xl text-white'></i></div></div><div class="ep-meta"><div class="ep-title">${title}</div><div class="ep-desc">${desc}</div></div></div>${dlLink ? `<a href="${dlLink}" target="_blank" class="dl-icon-btn"><i class='bx bxs-download'></i></a>` : ''}</div>`;
    });
    list.innerHTML = html;
    if(streams.length > 0) { const firstUrl = streams[0].getAttribute('onclick')?.match(/'(.*?)'/)?.[1]; if(firstUrl) playUrl(firstUrl); }
}

async function fetchTMDB(query) {
    try {
        const clean = query.replace(/\(\d{4}\)/, '').trim();
        const res = await fetch(`${TMDB_BASE}/search/multi?api_key=${API_KEY}&query=${encodeURIComponent(clean)}`);
        const data = await res.json();
        return data.results[0];
    } catch(e) { return null; }
}

window.playUrl = (url) => { document.getElementById('main-player').src = url; window.scrollTo({top:0, behavior:'smooth'}); }
function getMatch(content, cls) { const regex = new RegExp(`class=["']${cls}["'][^>]*>(.*?)<\/div>`); const match = content.match(regex); return match ? match[1] : ''; }
//
